def separate_paren_groups(paren_string: str) -> List[str]:
    """
    Separates groups of nested parentheses into separate strings.

    :param paren_string: A string containing multiple groups of nested parentheses.
    :return: A list of strings, each representing a separate group of balanced parentheses.
    """
    result = []
    current_group = []
    balance = 0

    for char in paren_string:
        if char == ' ':
            continue
        current_group.append(char)
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1

        if balance == 0 and current_group:
            result.append(''.join(current_group))
            current_group = []

    if balance != 0:
        raise ValueError("Input string is not balanced")

    return result

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for operation in operations:
        balance += operation
        if balance < 0:
            return True
    return False

def find_topmost_carpet(n, carpets, point) -> int:
    x, y = point
    topmost_carpet = -1
    for i in range(n-1, -1, -1):
        a, b, g, k = carpets[i]
        if a <= x <= a + g and b <= y <= b + k:
            topmost_carpet = i + 1
            break
    return topmost_carpet

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    from functools import lru_cache

    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]

    # Fill the grid with the given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    @lru_cache(None)
    def dp(r1, c1, r2):
        c2 = r1 + c1 - r2
        # Base case: out of bounds or invalid cell
        if r1 >= N or c1 >= N or r2 >= N or c2 >= N or grid[r1][c1] == -1 or grid[r2][c2] == -1:
            return float('-inf')
        # If both are at the end, return the value at the end cell
        if r1 == N-1 and c1 == N-1:
            return grid[r1][c1]
        # Calculate the value collected at the current positions
        value = grid[r1][c1]
        if r1 != r2 or c1 != c2:
            value += grid[r2][c2]
        # Recursive calls to explore all possible paths
        return value + max(
            dp(r1 + 1, c1, r2 + 1),
            dp(r1 + 1, c1, r2),
            dp(r1, c1 + 1, r2 + 1),
            dp(r1, c1 + 1, r2)
        )

    # Mark the cells with obstacles if needed (not required in this problem)

    # Start the dynamic programming process
    result = dp(0, 0, 0)

    # If no valid path was found, return 0
    return result if result != float('-inf') else 0

