    if A == B:
        return 0

    queue = deque([(A, 0)])  # Queue of (current_string, current_step_count)
    visited = set()  # Set to keep track of visited strings to avoid cycles

    while queue:
        current, steps = queue.popleft()

        if steps >= 10:
            continue  # Stop exploring if more than 10 steps

        for src, tgt in rules:
            start = 0
            while start < len(current):
