def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    for participant, statement_list in statements.items():
        for statement in statement_list:
            if statement in days_of_week:
                continue  # Ignore statements about the day of the week
            if participant == scenario:  # The scenario participant
                if statement == "I am guilty." and participant in liar_count:
                    return False  # Scenario participant claims guilt but is a liar
                elif statement == "I am not guilty." and participant not in liar_count:
                    return False  # Scenario participant denies guilt but is truth-teller
            else:  # Other participants
                if f"{participant} is guilty." in statement and participant not in liar_count and scenario != participant:
                    return False  # Truth-teller claims participant is guilty, but scenario says otherwise
                elif f"{participant} is not guilty." in statement and participant not in liar_count and scenario == participant:
                    return False  # Truth-teller claims participant is not guilty, but scenario says otherwise
                elif f"{participant} is guilty." in statement and participant in liar_count and scenario == participant:
                    return False  # Liar claims participant is guilty, but scenario says otherwise
                elif f"{participant} is not guilty." in statement and participant in liar_count and scenario != participant:
                    return False  # Liar claims participant is not guilty, but scenario says otherwise
    return True

