def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize the DP array where dp[i] represents whether a volume 'i' can be achieved
    dp = [False] * (V + 1)
    dp[0] = True  # Base case: zero volume can always be achieved with no items

    # Iterate over each item
    for volume in volumes:
        # Traverse the dp array backwards to avoid using the same item multiple times
        for j in range(V, volume - 1, -1):
            if dp[j - volume]:
                dp[j] = True

    # Find the maximum volume that can be achieved without exceeding V
    max_achievable_volume = 0
    for i in range(V, -1, -1):
        if dp[i]:
            max_achievable_volume = i
            break

    # The minimum remaining space is the difference between the total capacity and the max achievable volume
    return V - max_achievable_volume

